export function ListDemo({
  heading = "{{heading}}",
  variant = "{{variant}}",
  density = "{{density}}",
  empty = {{empty}},
  showExtra = {{showExtra}},
  accent = "{{accent}}",
}) {
  const compact = density === "compact";
  const itemStyle = {
    display: "flex", alignItems: "center", gap: 10,
    padding: compact ? "6px 4px" : "12px 4px",
    fontSize: compact ? 13 : 14,
    borderBottom: variant === "divided" ? "1px solid #24143020" : "none",
    background: variant === "card" ? "#fff" : "transparent",
    borderRadius: variant === "card" ? 8 : 0,
    marginBottom: variant === "card" ? (compact ? 6 : 8) : 0,
    boxShadow: variant === "card" ? "0 2px 8px rgba(36,20,48,.08)" : "none",
  };
  const badge = { display: "inline-flex", alignItems: "center", justifyContent: "center", width: 22, height: 22, borderRadius: "50%", background: accent, color: "#241430", fontSize: 12, fontWeight: 700, flexShrink: 0 };
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 16, lineHeight: 1.5, color: "#241430", background: "#FAF7F2", borderRadius: 12, padding: 20, maxWidth: 340, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 12px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      {empty ? (
        <p style={{ margin: 0, padding: "24px 12px", textAlign: "center", fontSize: 13, color: "#241430aa", border: "1.5px dashed #24143033", borderRadius: 10 }}>
          No items yet — check back soon.
        </p>
      ) : (
        <ol style={{ listStyle: "none", margin: 0, padding: 0 }}>
          <li style={itemStyle}><span style={badge}>1</span><span>Create your workspace</span></li>
          <li style={itemStyle}><span style={badge}>2</span><span>Invite your team</span></li>
          <li style={itemStyle}><span style={badge}>3</span><span>Connect a data source</span></li>
          {showExtra && (
            <li style={itemStyle}><span style={badge}>4</span><span>Publish your first report</span></li>
          )}
        </ol>
      )}
    </div>
  );
}
